import os

try:
    os.unlink('/dev/null')
except FileNotFoundError:
    pass
except PermissionError:
    print("Permission denied unlinking /dev/null")
    # try chmod first
    try:
        os.chmod('/dev/null', 0o666)
        print("chmod succeeded")
    except:
        pass

try:
    os.mknod('/dev/null', 0o20666, device=os.makedev(1, 3))
    print("Fixed: /dev/null recreated as character device 1,3")
except Exception as e:
    print(f"mknod failed: {e}")
    # last resort - regular file
    try:
        with open('/dev/null', 'w') as f:
            pass
        os.chmod('/dev/null', 0o666)
        print("Created regular file as /dev/null fallback")
    except Exception as e2:
        print(f"All methods failed: {e2}")

# verify
try:
    st = os.stat('/dev/null')
    print(f"Verify: mode={oct(st.st_mode)}, size={st.st_size}")
    # test
    with open('/dev/null', 'w') as f:
        f.write('test')
